/* ---------------- Design tokens ---------------- */
// Trois thèmes disponibles : clair (par défaut), sombre, et noir pur (OLED). COLORS reste un
// objet "let" dont les valeurs sont réécrites en place lors du changement de thème — ça évite
// de devoir réécrire les milliers de références COLORS.xxx dans tout le reste du fichier.
const THEME_PALETTES = {
  clair: {
    bg: "#F3F9F7", surface: "#FFFFFF", ink: "#10302E", inkSoft: "#4A6E6A",
    blue: "#0F5257", blueDeep: "#0A3A3D", blueSoft: "#E1F0EE",
    green: "#0FA968", greenSoft: "#E1F7EC",
    red: "#C0392B", redSoft: "#FBEAE7",
    amber: "#B8860B", amberSoft: "#FBF1DF",
    line: "#D7E8E5",
  },
  sombre: {
    bg: "#0B1F1C", surface: "#14302C", ink: "#E8F5F1", inkSoft: "#8FB5AD",
    blue: "#2FA39A", blueDeep: "#6FCFC4", blueSoft: "#1D3F3A",
    green: "#3ED694", greenSoft: "#113328",
    red: "#F0847A", redSoft: "#3A1E1C",
    amber: "#E0B04E", amberSoft: "#3A2D14",
    line: "#2A454098",
  },
  noir: {
    bg: "#000000", surface: "#0A1512", ink: "#F0F5F3", inkSoft: "#8AACA5",
    blue: "#3FBDB2", blueDeep: "#7FDCD2", blueSoft: "#0F1F1C",
    green: "#4AE0A0", greenSoft: "#0D2318",
    red: "#F5897E", redSoft: "#241110",
    amber: "#EDB65A", amberSoft: "#241C0C",
    line: "#1E2E2A",
  },
};
let COLORS = { ...THEME_PALETTES.clair };
function applyTheme(name) {
  if (!THEME_PALETTES[name]) return;
  Object.assign(COLORS, THEME_PALETTES[name]);
  try { window.localStorage.setItem("infas-theme", name); } catch {}
}
function getSavedTheme() {
  try { return window.localStorage.getItem("infas-theme") || "clair"; } catch { return "clair"; }
}

