// Palette de teintes, une par UE, utilisée pour la couleur d'accent de l'UE et le fond tamisé de ses ECUE
const UE_PALETTE = ["#0B5D8C", "#1E8F5E", "#A8720F", "#B23A2E", "#2D6E6B", "#0E7C86", "#9C5B0B", "#3D6B99", "#7A3B8C", "#5C7A0B"];
const UE_COLOR = Object.fromEntries(UE_LIST.map((u, i) => [u.id, UE_PALETTE[i % UE_PALETTE.length]]));

const SUBJ = Object.fromEntries(ECUE_LIST.filter((e) => e.subjectId).map((e) => [e.subjectId, e.label]));

/* ============================================================
   DÉFI INFIRMIER MODEL — espace détaché, classement pondéré par les
   coefficients (crédits) officiels de chaque matière, actualisé en direct.
   ============================================================ */

// Poids (coefficient) de chaque matière = somme des crédits de ses ECUE dans le
// programme officiel — exactement la logique de pondération réelle du cursus.
const SUBJECT_CREDITS = ECUE_LIST.filter((e) => e.subjectId).reduce((acc, e) => {
  acc[e.subjectId] = (acc[e.subjectId] || 0) + (e.credits || 1);
  return acc;
}, {});

// Mois courant (ex. "2026-07"), sert de clé de cycle mensuel du défi. La répartition
// des tentatives par matière au fil du mois est laissée entièrement libre à l'étudiant ;
// le nombre de matières tentées est affiché en toute transparence à côté de chaque score
// du classement plutôt que d'imposer un minimum obligatoire.
function currentIsoMonth(d = new Date()) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
}

function defiKey(matricule, isoMonth) {
  return `defi:${isoMonth}:${matricule}`;
}

// Enregistre la meilleure tentative du mois pour UNE matière (si le nouveau
// score est meilleur que l'ancien, sinon on ne touche à rien — "meilleure tentative").
// La "semaine en cours" pour un étudiant donné n'est PAS liée au calendrier : c'est la
// prochaine semaine non encore validée (semaine 1 → 2 → 3 → 4, strictement dans l'ordre).
// Ça permet à un étudiant qui commence en retard ou qui a manqué une semaine de
// rattraper sans jamais pouvoir "sauter" une étape.
function nextWeekToPlay(weeksCompleted = []) {
  for (let w = 1; w <= 4; w++) {
    if (!weeksCompleted.includes(w)) return w;
  }
  return null; // les 4 semaines sont validées pour ce mois
}

const TOTAL_COEF = Object.values(SUBJECT_CREDITS).reduce((a, b) => a + b, 0);
// Quotas précis par semaine (somme = coefficient total du programme, 26,5) : légèrement
// dégressifs pour laisser plus de marge en fin de mois. L'étudiant choisit librement
// quelles matières combiner pour atteindre le quota de chaque semaine.
const WEEKLY_TARGETS = [7.5, 7, 6, 6];

async function loadDefiRecord(matricule, isoMonth = currentIsoMonth()) {
  try {
    const r = await storage.get(defiKey(matricule, isoMonth), true);
    return r ? JSON.parse(r.value) : null;
  } catch {
    return null;
  }
}

async function saveDefiAttempt(student, subjectId, note20, week) {
  const isoMonth = currentIsoMonth();
  const key = defiKey(student.matricule, isoMonth);
  let record = await loadDefiRecord(student.matricule, isoMonth);
  if (!record) {
    record = { matricule: student.matricule, prenom: student.prenom, nom: student.nom, isoMonth, scores: {}, weeksCompleted: [] };
  }
  if (!record.weeksCompleted) record.weeksCompleted = [];
  // Une matière tentée est définitive pour le mois (une seule chance, pas de retenter) :
  // on n'écrase jamais un score déjà enregistré.
  if (!record.scores[subjectId]) {
    record.scores[subjectId] = { note20, week };
  }
  await storage.set(key, JSON.stringify(record), true);
  return record;
}

// Marque la semaine en cours comme définitivement validée : une fois le combo de la
// semaine lancé et terminé, impossible d'en relancer un autre la même semaine.
async function markWeekCompleted(student, week) {
  const isoMonth = currentIsoMonth();
  const key = defiKey(student.matricule, isoMonth);
  let record = await loadDefiRecord(student.matricule, isoMonth);
  if (!record) {
    record = { matricule: student.matricule, prenom: student.prenom, nom: student.nom, isoMonth, scores: {}, weeksCompleted: [] };
  }
  if (!record.weeksCompleted) record.weeksCompleted = [];
  if (!record.weeksCompleted.includes(week)) record.weeksCompleted.push(week);
  await storage.set(key, JSON.stringify(record), true);
  return record;
}

// Moyenne pondérée par les coefficients, uniquement sur les matières que l'étudiant
// a déjà tentées ce mois (ne pénalise pas les matières pas encore couvertes) ; le
// nombre de matières tentées reste affiché en clair pour garder le classement transparent.
function computeWeightedAverage(scores) {
  const entries = Object.entries(scores || {});
  if (entries.length === 0) return null;
  let totalPoints = 0;
  let totalCoef = 0;
  entries.forEach(([subjectId, entry]) => {
    const note20 = typeof entry === "number" ? entry : entry.note20; // rétrocompatibilité ancien format
    const coef = SUBJECT_CREDITS[subjectId] || 1;
    totalPoints += note20 * coef;
    totalCoef += coef;
  });
  return totalCoef > 0 ? totalPoints / totalCoef : null;
}

// Coefficient cumulé atteint par l'étudiant POUR LA SEMAINE EN COURS du mois (somme des
// coefficients des matières dont la première tentative date de cette semaine-là).
function computeWeekCoefProgress(scores, week) {
  return Object.entries(scores || {}).reduce((sum, [subjectId, entry]) => {
    const entryWeek = typeof entry === "number" ? 1 : entry.week; // rétrocompatibilité
    if (entryWeek !== week) return sum;
    return sum + (SUBJECT_CREDITS[subjectId] || 1);
  }, 0);
}

// Classement du mois en cours : tous les étudiants ayant au moins une tentative,
// triés par moyenne pondérée décroissante.
async function loadDefiLeaderboard(isoMonth = currentIsoMonth()) {
  try {
    const list = await storage.list(`defi:${isoMonth}:`, true);
    if (!list || !list.keys) return [];
    const records = await Promise.all(
      list.keys.map(async (k) => {
        const fullKey = k.startsWith("defi:") ? k : `defi:${isoMonth}:${k}`;
        try {
          const r = await storage.get(fullKey, true);
          return r ? JSON.parse(r.value) : null;
        } catch {
          return null;
        }
      })
    );
    return records
      .filter(Boolean)
      .map((rec) => ({ ...rec, moyennePonderee: computeWeightedAverage(rec.scores), nbMatieres: Object.keys(rec.scores || {}).length }))
      .filter((rec) => rec.moyennePonderee !== null)
      .sort((a, b) => b.moyennePonderee - a.moyennePonderee);
  } catch (e) {
    console.error("Erreur chargement classement défi", e);
    return [];
  }
}

// Moyenne pondérée calculée UNIQUEMENT sur les matières tentées durant une semaine précise
// (pas le cumul du mois) — sert au classement hebdomadaire archivé S1/S2/S3/S4.
function computeWeekWeightedAverage(scores, week) {
  const entries = Object.entries(scores || {}).filter(([, entry]) => {
    const entryWeek = typeof entry === "number" ? 1 : entry.week;
    return entryWeek === week;
  });
  if (entries.length === 0) return null;
  let totalPoints = 0;
  let totalCoef = 0;
  entries.forEach(([subjectId, entry]) => {
    const note20 = typeof entry === "number" ? entry : entry.note20;
    const coef = SUBJECT_CREDITS[subjectId] || 1;
    totalPoints += note20 * coef;
    totalCoef += coef;
  });
  return totalCoef > 0 ? totalPoints / totalCoef : null;
}

// Classement archivé d'UNE semaine précise du mois — chaque mois garde ses 4 classements
// hebdomadaires distincts en plus du classement final, tous recalculés à partir des mêmes
// données déjà stockées (rien à archiver manuellement, la clé "defi:{mois}:..." fait déjà
// tout le travail de conservation d'un mois à l'autre).
async function loadDefiWeekLeaderboard(isoMonth, week) {
  try {
    const list = await storage.list(`defi:${isoMonth}:`, true);
    if (!list || !list.keys) return [];
    const records = await Promise.all(
      list.keys.map(async (k) => {
        const fullKey = k.startsWith("defi:") ? k : `defi:${isoMonth}:${k}`;
        try {
          const r = await storage.get(fullKey, true);
          return r ? JSON.parse(r.value) : null;
        } catch {
          return null;
        }
      })
    );
    return records
      .filter(Boolean)
      .map((rec) => ({ ...rec, moyenneSemaine: computeWeekWeightedAverage(rec.scores, week) }))
      .filter((rec) => rec.moyenneSemaine !== null)
      .sort((a, b) => b.moyenneSemaine - a.moyenneSemaine);
  } catch (e) {
    console.error("Erreur chargement classement hebdomadaire", e);
    return [];
  }
}

function displayName(prenom, nom) {
  return `${prenom || ""} ${nom ? nom[0].toUpperCase() + "." : ""}`.trim();
}

