function buildCases(rawCases, subjectId, prefix) {
  return rawCases.map((c, ci) => ({
    id: `${prefix}${ci + 1}`,
    subjectId,
    chapterId: c.chapterId,
    chapterLabel: CH[c.chapterId],
    level: c.level,
    vignette: c.vignette,
    reference: c.ref,
    questions: c.qs.map((q, qi) => ({
      id: `${prefix}${ci + 1}-q${qi + 1}`,
      type: "QCM",
      chapterId: c.chapterId,
      chapterLabel: CH[c.chapterId],
      stem: q.stem,
      options: q.options.map((t, idx) => ({ id: `${prefix}c${ci}-${qi}-${idx}`, text: t, correct: q.correct.includes(idx) })),
      explanation: q.explanation,
      reference: c.ref,
      isCase: true,
      caseId: `${prefix}${ci + 1}`,
      caseVignette: c.vignette,
    })),
  }));
}
const CASES = [
  ...buildCases(RAW_CASES, "hematologie", "case"),
  ...buildCases(DEONTO_RAW_CASES, "deontologie", "dcase"),
];

/* ---------------- Levels ---------------- */
const LEVELS = [
  { id: "debutant", label: "Débutant", maxLevel: 1, numSingle: 10, numCases: 0, desc: "Bases du cours, notions clés", timePerQuestion: null },
  { id: "intermediaire", label: "Intermédiaire", maxLevel: 2, numSingle: 14, numCases: 1, desc: "Interprétation des constantes", timePerQuestion: null },
  { id: "avance", label: "Avancé", maxLevel: 3, numSingle: 30, numCases: 2, desc: "Raisonnement clinique, chronométré", timePerQuestion: 25 },
  { id: "concours", label: "Niveau concours", maxLevel: 4, numSingle: 40, numCases: 2, desc: "Épreuve complète type concours, chronométrée", timePerQuestion: 20 },
];

/* ---------------- Exam generation ---------------- */
function generateExam(subjectId, levelId, seen = { q: [], c: [] }) {
  const cfg = LEVELS.find((l) => l.id === levelId);
  const seenQ = new Set(seen.q || []);
  const seenC = new Set(seen.c || []);

  const pool = QUESTIONS.filter((q) => q.subjectId === subjectId && q.level <= cfg.maxLevel);
  const byChapter = {};
  pool.forEach((q) => {
    byChapter[q.chapterId] = byChapter[q.chapterId] || [];
    byChapter[q.chapterId].push(q);
  });
  // au sein de chaque chapitre : questions jamais vues récemment en premier, puis les déjà vues
  Object.keys(byChapter).forEach((k) => {
    const unseen = shuffle(byChapter[k].filter((q) => !seenQ.has(q.id)));
    const already = shuffle(byChapter[k].filter((q) => seenQ.has(q.id)));
    byChapter[k] = [...unseen, ...already];
  });
  const chapterOrder = shuffle(Object.keys(byChapter));

  const picked = [];
  let round = 0;
  while (picked.length < cfg.numSingle) {
    let addedThisRound = false;
    for (const chId of chapterOrder) {
      if (picked.length >= cfg.numSingle) break;
      const arr = byChapter[chId];
      if (arr && arr[round]) {
        picked.push(arr[round]);
        addedThisRound = true;
      }
    }
    round++;
    if (!addedThisRound) break;
  }

  const casePoolAll = CASES.filter((c) => c.subjectId === subjectId && c.level <= cfg.maxLevel);
  const unseenCases = shuffle(casePoolAll.filter((c) => !seenC.has(c.id)));
  const alreadyCases = shuffle(casePoolAll.filter((c) => seenC.has(c.id)));
  const casePool = [...unseenCases, ...alreadyCases];
  const pickedCases = casePool.slice(0, cfg.numCases);

  // randomize option order per question, preserving correctness
  const randomizeOptions = (q) => ({ ...q, options: shuffle(q.options) });

  const singleItems = shuffle(picked).map((q) => ({ kind: "single", ...randomizeOptions(q) }));
  const caseItems = pickedCases.map((c) => ({
    kind: "case",
    id: c.id,
    chapterLabel: c.chapterLabel,
    vignette: c.vignette,
    reference: c.reference,
    questions: c.questions.map(randomizeOptions),
  }));

  // interleave: place cases after roughly 1/3 and 2/3 of singles
  const items = [];
  const segments = caseItems.length + 1;
  const chunk = Math.ceil(singleItems.length / segments);
  let idx = 0;
  caseItems.forEach((c) => {
    items.push(...singleItems.slice(idx, idx + chunk));
    idx += chunk;
    items.push(c);
  });
  items.push(...singleItems.slice(idx));

  return {
    subjectId, levelId, items, generatedAt: new Date().toISOString(),
    usedQIds: picked.map((q) => q.id),
    usedCIds: pickedCases.map((c) => c.id),
  };
}

// combine newly-used ids into the persisted "seen" record; once every item of a
// pool has been shown at least once, start a fresh cycle instead of getting stuck
function updateSeen(seen, exam) {
  const mergedQ = Array.from(new Set([...(seen.q || []), ...exam.usedQIds]));
  const mergedC = Array.from(new Set([...(seen.c || []), ...exam.usedCIds]));
  const subjectQTotal = QUESTIONS.filter((q) => q.subjectId === exam.subjectId).length;
  const subjectCTotal = CASES.filter((c) => c.subjectId === exam.subjectId).length;
  const nextQ = mergedQ.length >= subjectQTotal ? exam.usedQIds : mergedQ;
  const nextC = mergedC.length >= subjectCTotal ? exam.usedCIds : mergedC;
  return { q: nextQ, c: nextC };
}

// mode entraînement : pas de limite de temps, feedback immédiat après chaque
// réponse. On peut réviser un chapitre précis ou l'ensemble du cours.
function generateTraining(subjectId, chapterId) {
  const qPool = QUESTIONS.filter((q) => q.subjectId === subjectId && (chapterId === "all" || q.chapterId === chapterId));
  const cPool = CASES.filter((c) => c.subjectId === subjectId && (chapterId === "all" || c.chapterId === chapterId));
  const randomizeOptions = (q) => ({ ...q, options: shuffle(q.options) });

  const singleItems = shuffle(qPool).map((q) => ({ kind: "single", ...randomizeOptions(q) }));
  const caseItems = shuffle(cPool).map((c) => ({
    kind: "case",
    id: c.id,
    chapterLabel: c.chapterLabel,
    vignette: c.vignette,
    reference: c.reference,
    questions: c.questions.map(randomizeOptions),
  }));

  return { subjectId, chapterId, items: shuffle([...singleItems, ...caseItems]) };
}

function flattenGradable(items) {
  const flat = [];
  items.forEach((it) => {
    if (it.kind === "single") flat.push(it);
    else it.questions.forEach((q) => flat.push({ kind: "caseq", caseId: it.id, caseVignette: it.vignette, ...q }));
  });
  return flat;
}

/* ---------------- Scoring ---------------- */
function scoreExam(items, answers) {
  const flat = flattenGradable(items);
  let obtained = 0;
  let maxTotal = 0;
  let bonnes = 0, mauvaises = 0, oubliees = 0;
  const chapterStats = {};
  const details = flat.map((q) => {
    const sel = answers[q.id] || [];
    const correctIds = q.options.filter((o) => o.correct).map((o) => o.id);
    let pts, max;
    if (q.type === "QCU") {
      max = 1;
      pts = sel.length === 1 && correctIds.includes(sel[0]) ? 1 : 0;
    } else {
      max = correctIds.length;
      const rightPicked = sel.filter((s) => correctIds.includes(s)).length;
      const wrongPicked = sel.filter((s) => !correctIds.includes(s)).length;
      pts = Math.max(0, rightPicked - wrongPicked);
    }
    obtained += pts;
    maxTotal += max;

    let status;
    if (sel.length === 0) { status = "oubliee"; oubliees++; }
    else {
      const selSet = new Set(sel);
      const corSet = new Set(correctIds);
      const exact = selSet.size === corSet.size && [...selSet].every((s) => corSet.has(s));
      if (exact) { status = "bonne"; bonnes++; } else { status = "mauvaise"; mauvaises++; }
    }

    chapterStats[q.chapterId] = chapterStats[q.chapterId] || { correct: 0, total: 0 };
    chapterStats[q.chapterId].total += 1;
    if (status === "bonne") chapterStats[q.chapterId].correct += 1;

    return { ...q, selected: sel, correctIds, points: pts, max, status };
  });

  const percent = maxTotal ? (obtained / maxTotal) * 100 : 0;
  const note20 = maxTotal ? (obtained / maxTotal) * 20 : 0;

  return { obtained, maxTotal, percent, note20, bonnes, mauvaises, oubliees, chapterStats, details, totalItems: flat.length };
}

/* ---------------- Storage ---------------- */
// L'historique et le suivi des questions vues sont désormais rattachés au numéro
// de téléphone du candidat et stockés en mémoire partagée (Netlify Blobs en
// production) : peu importe l'appareil utilisé, se reconnecter avec le même
// numéro retrouve exactement le même compte, comme demandé.
function sanitizeKeyPart(s) {
  return (s || "").replace(/[^A-Za-z0-9+]/g, "");
}
function historyKey(matricule) {
  return `infas-hemato:history:${sanitizeKeyPart(matricule)}`;
}
function seenKey(matricule) {
  return `infas-hemato:seen:${sanitizeKeyPart(matricule)}`;
}

async function loadHistory(matricule) {
  try {
    const res = await storage.get(historyKey(matricule), true);
    return res ? JSON.parse(res.value) : [];
  } catch {
    return [];
  }
}
async function saveHistory(matricule, history) {
  try {
    await storage.set(historyKey(matricule), JSON.stringify(history), true);
  } catch (e) {
    console.error("Erreur de sauvegarde", e);
  }
}

/* ---- Suivi des questions/cas déjà vus, pour éviter les répétitions d'une connexion à l'autre ---- */
async function loadSeen(matricule) {
  try {
    const res = await storage.get(seenKey(matricule), true);
    return res ? JSON.parse(res.value) : { q: [], c: [] };
  } catch {
    return { q: [], c: [] };
  }
}
async function saveSeen(matricule, seen) {
  try {
    await storage.set(seenKey(matricule), JSON.stringify(seen), true);
  } catch (e) {
    console.error("Erreur de sauvegarde (suivi des questions vues)", e);
  }
}

/* ---- Comptes étudiants (matricule = identifiant, année de naissance = mot de passe) ---- */
const STUDENT_PREFIX = "infas-hemato:student:";
const TRIAL_DAYS = 15;
const PAID_DAYS = 365; // repli si un compte "paid" existant n'a pas de plan enregistré

const SUBSCRIPTION_PLANS = [
  { id: "1mois", label: "1 mois", price: 300, days: 30, url: "https://pay.wave.com/m/M_ci_gbhLy18P_Mhs/c/ci/?amount=300", color: "#1E8F5E" },
  { id: "2mois", label: "2 mois", price: 500, days: 60, url: "https://pay.wave.com/m/M_ci_gbhLy18P_Mhs/c/ci/?amount=500", color: "#0B5D8C" },
  { id: "6mois", label: "6 mois", price: 1000, days: 180, url: "https://pay.wave.com/m/M_ci_gbhLy18P_Mhs/c/ci/?amount=1000", color: "#2D6E6B" },
];

function studentKey(matricule) {
  return `${STUDENT_PREFIX}${sanitizeKeyPart(matricule)}`;
}

async function findStudent(matricule) {
  try {
    const r = await storage.get(studentKey(matricule), true);
    return r ? JSON.parse(r.value) : null;
  } catch {
    return null;
  }
}

async function createStudent(profile) {
  const now = new Date().toISOString();
  const record = {
    matricule: profile.matricule,
    anneeNaissance: profile.anneeNaissance,
    nom: profile.nom,
    prenom: profile.prenom,
    antenne: profile.antenne,
    niveau: profile.niveau,
    specialite: profile.specialite,
    createdAt: now,
    lastSeen: now,
    examsCount: 0,
    paymentStatus: "trial", // trial | pending | paid
    paidAt: null,
    paidDays: null,
    pendingSince: null,
    pendingPlan: null,
  };
  try {
    await storage.set(studentKey(profile.matricule), JSON.stringify(record), true);
    return record;
  } catch (e) {
    console.error("Erreur création compte", e);
    return null;
  }
}

async function touchStudentLastSeen(matricule) {
  try {
    const r = await storage.get(studentKey(matricule), true);
    if (!r) return;
    const rec = JSON.parse(r.value);
    rec.lastSeen = new Date().toISOString();
    await storage.set(studentKey(matricule), JSON.stringify(rec), true);
  } catch (e) {
    console.error("Erreur mise à jour compte", e);
  }
}

// Réinitialisation ponctuelle (une seule fois par compte) : au passage de l'essai gratuit de
// 45 à 15 jours, chaque étudiant déjà inscrit, non-VIP et non-payant, reçoit un nouveau départ
// de compteur de 15 jours à partir de sa prochaine connexion, au lieu de subir la réduction
// rétroactive sur son ancienne date d'inscription. Ne s'applique qu'une seule fois par compte
// (marqueur trialReset15Applied), pour ne jamais réinitialiser le compteur à chaque connexion.
async function applyTrialReset15IfNeeded(student) {
  if (!student) return student;
  if (student.paymentStatus === "paid" && student.paidAt) return student;
  if (isVIPMatricule(student.matricule)) return student;
  if (student.trialReset15Applied) return student;
  const now = new Date().toISOString();
  const updated = { ...student, trialResetAt: now, trialReset15Applied: true };
  try {
    await storage.set(studentKey(student.matricule), JSON.stringify(updated), true);
  } catch (e) {
    console.error("Erreur réinitialisation essai 15 jours", e);
  }
  return updated;
}

async function incrementStudentExamCount(matricule) {
  try {
    const r = await storage.get(studentKey(matricule), true);
    if (!r) return;
    const rec = JSON.parse(r.value);
    rec.examsCount = (rec.examsCount || 0) + 1;
    rec.lastSeen = new Date().toISOString();
    await storage.set(studentKey(matricule), JSON.stringify(rec), true);
  } catch (e) {
    console.error("Erreur mise à jour compte", e);
  }
}

async function markPaymentPending(matricule, planId) {
  try {
    const r = await storage.get(studentKey(matricule), true);
    if (!r) return null;
    const rec = JSON.parse(r.value);
    rec.paymentStatus = "pending";
    rec.pendingSince = new Date().toISOString();
    rec.pendingPlan = planId;
    await storage.set(studentKey(matricule), JSON.stringify(rec), true);
    return rec;
  } catch (e) {
    console.error("Erreur signalement paiement", e);
    return null;
  }
}

async function confirmPayment(matricule) {
  try {
    const r = await storage.get(studentKey(matricule), true);
    if (!r) return null;
    const rec = JSON.parse(r.value);
    const plan = SUBSCRIPTION_PLANS.find((p) => p.id === rec.pendingPlan);
    rec.paymentStatus = "paid";
    rec.paidAt = new Date().toISOString();
    rec.paidDays = plan ? plan.days : PAID_DAYS;
    rec.pendingSince = null;
    rec.pendingPlan = null;
    await storage.set(studentKey(matricule), JSON.stringify(rec), true);
    return rec;
  } catch (e) {
    console.error("Erreur confirmation paiement", e);
    return null;
  }
}

// Permet à l'administrateur de consulter le mot de passe réel (année de naissance) d'un
// étudiant inscrit, et de le modifier au besoin pour le lui retransmettre en cas d'oubli.
async function updateStudentPassword(matricule, newAnneeNaissance) {
  try {
    const r = await storage.get(studentKey(matricule), true);
    if (!r) return null;
    const rec = JSON.parse(r.value);
    rec.anneeNaissance = newAnneeNaissance.trim();
    await storage.set(studentKey(matricule), JSON.stringify(rec), true);
    return rec;
  } catch (e) {
    console.error("Erreur modification mot de passe", e);
    return null;
  }
}

// Supprime définitivement un compte étudiant et toutes les données associées
// (fiche, historique d'examens, suivi anti-répétition, progression schémas, notes).
async function deleteStudentAccount(matricule) {
  try {
    await Promise.all([
      storage.delete(studentKey(matricule), true),
      storage.delete(historyKey(matricule), true),
      storage.delete(seenKey(matricule), true),
      storage.delete(schemaKey(matricule), false),
      storage.delete(myNotesKey(matricule), false),
    ]);
    return true;
  } catch (e) {
    console.error("Erreur suppression compte", e);
    return false;
  }
}

async function loadAllStudents() {
  try {
    const listRes = await storage.list(STUDENT_PREFIX, true);
    const keys = listRes?.keys || [];
    const records = [];
    for (const k of keys) {
      try {
        const r = await storage.get(k, true);
        if (r) records.push(JSON.parse(r.value));
      } catch {
        /* skip unreadable entry */
      }
    }
    return records;
  } catch (e) {
    console.error("Erreur chargement comptes étudiants", e);
    return [];
  }
}

// Calcule l'accès en cours : essai gratuit à l'inscription, ou la durée du forfait payé
// (30 / 90 / 365 jours) à partir de la date de paiement confirmée par l'administrateur.
// Les comptes VIP (équipe) ont un accès illimité, sans jamais passer par l'essai ou le paiement.
function computeAccess(student) {
  if (!student) return { isBlocked: true, daysLeft: 0, totalDays: TRIAL_DAYS, isPaid: false, isVIP: false };
  if (isVIPMatricule(student.matricule)) {
    return { isBlocked: false, daysLeft: Infinity, totalDays: Infinity, isPaid: true, isVIP: true };
  }
  const now = Date.now();
  const isPaid = student.paymentStatus === "paid" && student.paidAt;
  // La bascule de l'essai gratuit à 15 jours (contre 45 auparavant) a été appliquée à tous les
  // comptes non-VIP et non-payants au moment de la mise à jour : trialResetAt marque ce nouveau
  // départ de compteur, prioritaire sur la date d'inscription d'origine (createdAt).
  const trialStart = student.trialResetAt || student.createdAt;
  const start = isPaid ? new Date(student.paidAt).getTime() : new Date(trialStart).getTime();
  const totalDays = isPaid ? (student.paidDays || PAID_DAYS) : TRIAL_DAYS;
  const elapsedDays = (now - start) / 86400000;
  const daysLeft = Math.max(0, Math.ceil(totalDays - elapsedDays));
  return { isBlocked: daysLeft <= 0, daysLeft, totalDays, isPaid, isVIP: false };
}


/* ---- Annonces admin (emplois du temps, infos, programmes de compos) ciblées par antenne/niveau/spécialité ---- */
const ANNOUNCEMENTS_KEY = "infas-hemato:announcements";

async function loadAnnouncements() {
  try {
    const r = await storage.get(ANNOUNCEMENTS_KEY, true);
    return r ? JSON.parse(r.value) : [];
  } catch {
    return [];
  }
}
async function saveAnnouncements(list) {
  try {
    await storage.set(ANNOUNCEMENTS_KEY, JSON.stringify(list), true);
  } catch (e) {
    console.error("Erreur sauvegarde annonces", e);
  }
}
function announcementMatches(a, student) {
  const antenneOk = !a.antennes || a.antennes.length === 0 || a.antennes.includes("toutes") || a.antennes.includes(student.antenne);
  const niveauOk = !a.niveau || a.niveau === "tous" || a.niveau === student.niveau;
  const specialiteOk = !a.specialite || a.specialite === "toutes" || a.specialite === student.specialite;
  return antenneOk && niveauOk && specialiteOk;
}

// Suivi de lecture des messages par étudiant : une fois un message ouvert dans l'écran
// dédié, son id est ajouté à la liste des messages lus, et le badge de la cloche se
// recalcule automatiquement (revient à 0 dès que tout est lu).
function readMessagesKey(matricule) {
  return `read-messages:${matricule}`;
}
async function loadReadMessageIds(matricule) {
  try {
    const r = await storage.get(readMessagesKey(matricule), false);
    return r ? JSON.parse(r.value) : [];
  } catch {
    return [];
  }
}
async function markMessagesRead(matricule, ids) {
  try {
    const current = await loadReadMessageIds(matricule);
    const merged = Array.from(new Set([...current, ...ids]));
    await storage.set(readMessagesKey(matricule), JSON.stringify(merged), false);
    return merged;
  } catch (e) {
    console.error("Erreur sauvegarde messages lus", e);
    return [];
  }
}

/* ================= MESSAGERIE (cloche) — autonome, distincte des Annonces ================
   Un message peut être individuel (targetMatricule renseigné) ou groupé (ciblage par
   antenne/niveau/spécialité, comme les annonces, mais stocké séparément). Aucune des deux
   fonctionnalités ne dépend de l'autre : "Annonces" garde son propre espace de stockage. */
const ADMIN_MESSAGES_KEY = "infas-hemato:admin-messages";

async function loadAdminMessages() {
  try {
    const r = await storage.get(ADMIN_MESSAGES_KEY, true);
    return r ? JSON.parse(r.value) : [];
  } catch {
    return [];
  }
}
async function saveAdminMessages(list) {
  try {
    await storage.set(ADMIN_MESSAGES_KEY, JSON.stringify(list), true);
  } catch (e) {
    console.error("Erreur sauvegarde messages admin", e);
  }
}
function adminMessageMatches(m, student) {
  // Message individuel : ne s'affiche que pour l'étudiant visé, quel que soit le reste.
  if (m.targetMatricule) return m.targetMatricule === student.matricule;
  // Message groupé : mêmes règles de ciblage que les annonces (antenne/niveau/spécialité).
  const antenneOk = !m.antennes || m.antennes.length === 0 || m.antennes.includes("toutes") || m.antennes.includes(student.antenne);
  const niveauOk = !m.niveau || m.niveau === "tous" || m.niveau === student.niveau;
  const specialiteOk = !m.specialite || m.specialite === "toutes" || m.specialite === student.specialite;
  return antenneOk && niveauOk && specialiteOk;
}

