// Hook "maison" reproduisant le comportement de react-headroom (masquer la barre au
// défilement vers le bas, la refaire apparaître vers le haut) — sans dépendance externe,
// react-headroom n'étant pas compatible avec React 19 utilisé par ce projet.
function useHeadroom() {
  const [visible, setVisible] = useState(true);
  useEffect(() => {
    let lastY = window.scrollY;
    let ticking = false;
    const onScroll = () => {
      if (ticking) return;
      ticking = true;
      requestAnimationFrame(() => {
        const y = window.scrollY;
        const delta = y - lastY;
        if (y < 60) {
          setVisible(true); // toujours visible tout en haut de la page
        } else if (delta > 6) {
          setVisible(false); // défilement vers le bas : on cache
        } else if (delta < -6) {
          setVisible(true); // défilement vers le haut : on réaffiche
        }
        lastY = y;
        ticking = false;
      });
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);
  return visible;
}

